                    "sql": "CREATE table if not exists prd_db.beardo.dwh_AMAZON_FACT_ITEMS ( Customer_id varchar,Shop_name varchar,Source varchar, order_id varchar, order_name varchar, phone varchar, name varchar, email varchar, shipping_last_update_date varchar, sku varchar, product_id varchar, product_name varchar, currency varchar, city varchar, state varchar, order_status varchar, order_timestamp varchar, shipping_price float, quantity float, discount_before_tax float, tax float, total_Sales float, is_refund number(38,0), product_name_final varchar, category varchar, product_sub_category varchar) ; create table if not exists prd_db.beardo.dwh_EasyEcom_FACT_ITEMS ( customer_id varchar, Shop_name varchar,marketplace varchar,Source varchar, order_id varchar, contact_num varchar, customer_name varchar, email varchar, shipping_last_update_date varchar, sku varchar, product_id varchar, productname varchar, currency varchar, city varchar, state varchar, order_status varchar, order_Date varchar, shipping_price float, suborder_quantity float, discount float, tax float, selling_price float, is_refund number(38,0), suborder_id variant, product_name_final varchar, product_category varchar, product_sub_category varchar, new_customer_flag varchar, shipping_status varchar, days_in_shipment varchar) ; create or replace table prd_db.beardo.dwh_sales_consolidated_pre_intermediate as select * from ( select b.customer_id ,\'SHOPIFY_BEARDO\' as shop_name ,UPPER(b.FINAL_UTM_CHANNEL) AS CHANNEL ,UPPER(b.FINAL_UTM_SOURCE) AS SOURCE ,b.ORDER_ID ,b.Order_Name as reference_code ,coalesce(b.phone ,c.contact_num) as phone ,coalesce(b.name ,c.Customer_Name) as Customer_Name ,coalesce(b.email ,c.email) as email ,coalesce(b.SHOPIFY_SHIPPING_UPDATED_DATE, c.shipping_last_update_date::datetime) AS SHIPPING_LAST_UPDATE_DATE ,coalesce(b.sku ,c.sku) as sku ,b.PRODUCT_ID ,b.PRODUCT_NAME ,b.CURRENCY ,Upper(b.CITY) City ,Upper(b.STATE) AS State ,upper(coalesce(c.order_status,b.order_status)) as Order_Status ,b.ORDER_TIMESTAMP::date AS Order_Date ,b.ORDER_TIMESTAMP ,b.line_item_sales ,b.SHIPPING_PRICE ,b.QUANTITY ,b.mrp_discount AS DISCOUNT ,b.TAX ,b.TOTAL_SALES AS SELLING_PRICE ,NULL AS SHIPPINGPACKAGECODE ,upper(coalesce(b.SHOPIFY_SHIPPING_STATUS, c.shipping_status)) AS SHIPPINGPACKAGESTATUS ,line_item_id::varchar as sales_order_item_id ,LINE_ITEM_ID::varchar as SALEORDERITEMCODE ,coalesce(c.invoice_id,b.LINE_ITEM_ID) as INVOICE_ID ,coalesce(c.courier ,b.SHOPIFY_COURIER) AS COURIER ,upper(coalesce(b.SHOPIFY_SHIPPING_STATUS,c.shipping_status)) AS SHIPPING_STATUS ,c.manifest_date::datetime AS DISPATCH_DATE ,case when upper(coalesce(b.SHOPIFY_SHIPPING_STATUS,c.shipping_status)) in (\'DELIVERED\') then 1 end AS DELIVERED_STATUS ,coalesce(c.IS_REFUND, b.IS_REFUND) AS RETURN_FLAG ,case when return_flag= 1 then quantity::int end returned_quantity ,case when return_flag = 0 and lower(coalesce(b.order_status,c.order_status)) in (\'cancelled\') then quantity::int end cancelled_quantity ,b.NEW_CUSTOMER_FLAG::varchar new_customer_flag ,b.ACQUISITION_PRODUCT ,case when upper(coalesce(b.SHOPIFY_SHIPPING_STATUS,c.shipping_status)) in (\'DELIVERED\',\'DELIVERED TO ORIGIN\', \'RETURNED\', \'RTO\') then datediff(day,date(b.ORDER_TIMESTAMP),date(shipping_Last_update_date)) else datediff(day,date(b.ORDER_TIMESTAMP), getdate()) end::int AS DAYS_IN_SHIPMENT ,NULL AS ACQUSITION_DATE ,coalesce(c.warehouse_name,\'NA\') as Warehouse_Name ,coalesce(s.Product_name_mapped,b.product_name,c.product_name) PRODUCT_NAME_FINAL ,coalesce(s.Product_Category_Mapped,c.product_category_mapped,b.category) PRODUCT_CATEGORY ,coalesce(s.Product_Sub_Category_Mapped,c.product_sub_category_mapped) PRODUCT_SUB_CATEGORY ,null as GA_SOURCE ,null as GA_MEDIUM ,null as VIEW_ID ,coalesce(b.payment_gateway_mapped,c.payment_mode) payment_mode ,b.discount_code ,b.affiliate ,b.tags as tag ,b.final_utm_content from prd_db.beardo.DWH_SHOPIFY_FACT_ITEMS b left join (select * from ( select *,row_number()over(partition by reference_code, order_Date order by last_update_date desc) rw from prd_db.beardo.dwh_unicommerce_fact_items ) z where z.rw = 1 ) c on lower(replace(b.order_name,\'#\',\'\')) = lower(c.reference_code) and b.order_timestamp::date = c.order_date::date left join (select distinct \"Product Code\" skucode, name Product_name_mapped, BUSINESS Product_category_mapped, \"Category Name\" Product_Sub_Category_Mapped from datalake_db.beardo.mst_mapping_sku_master) S on lower(b.sku)=lower(s.skucode) union all select Null as customer_id ,\'AMAZON\' as SHOP_NAME ,\'AMAZON\' as CHANNEL ,\'AMAZON\' AS SOURCE ,b.ORDER_ID ,b.Order_ID as reference_code ,coalesce(b.phone ,c.contact_num) as phone ,coalesce(b.name ,c.Customer_Name) as Customer_Name ,coalesce(b.email ,c.email) as email ,c.shipping_last_update_date::datetime AS SHIPPING_LAST_UPDATE_DATE ,coalesce(b.sku ,c.sku) as sku ,b.PRODUCT_ID ,b.PRODUCT_NAME ,b.CURRENCY ,upper(b.CITY) as City ,upper(b.STATE) AS State ,upper(coalesce(c.order_status,b.order_status)) as Order_Status ,b.ORDER_TIMESTAMP::date AS Order_Date ,b.ORDER_TIMESTAMP ,b.TOTAL_SALES line_item_sales ,b.SHIPPING_PRICE ,b.QUANTITY ,b.DISCOUNT_BEFORE_TAX AS DISCOUNT ,b.TAX ,b.TOTAL_SALES AS SELLING_PRICE ,NULL AS SHIPPINGPACKAGECODE ,coalesce(c.shipping_status ,NULL) AS SHIPPINGPACKAGESTATUS ,null as SALES_ORDER_ITEM_ID ,null as saleorderitemcode ,coalesce(c.invoice_id,null) as INVOICE_ID ,coalesce(c.courier ,NULL) AS COURIER ,upper(coalesce(c.shipping_status ,NULL)) AS SHIPPING_STATUS ,c.manifest_date::datetime AS DISPATCH_DATE ,NULL AS DELIVERED_STATUS ,coalesce(c.IS_REFUND, b.IS_REFUND) AS RETURN_FLAG ,case when return_flag = 1 then quantity::int end returned_quantity ,case when return_flag = 0 and lower(coalesce(c.order_status,b.order_status)) in (\'cancelled\') then quantity::int end cancelled_quantity ,NULL as NEW_CUSTOMER_FLAG ,NULL as ACQUISITION_PRODUCT ,case when upper(c.shipping_STATUS) in (\'DELIVERED\',\'DELIVERED TO ORIGIN\', \'RETURNED\', \'RTO\') then datediff(day,date(b.ORDER_TIMESTAMP),date(c.shipping_last_update_date::datetime)) else datediff(day,date(b.ORDER_TIMESTAMP), getdate()) end::int AS DAYS_IN_SHIPMENT ,NULL AS ACQUSITION_DATE ,coalesce(c.warehouse_name,\'NA\') as Warehouse_Name ,coalesce(b.product_name_final,c.Product_name_Mapped) PRODUCT_NAME_FINAL ,coalesce(b.category, c.product_category_mapped) PRODUCT_CATEGORY , Product_Sub_Category_Mapped Product_Sub_Category ,\'Amazon\' as GA_SOURCE ,\'Amazon\' as GA_MEDIUM ,null as VIEW_ID ,c.payment_mode payment_mode ,null as discount_code ,null as affiliate ,cast(null as string) as tag ,cast(null as string) final_utm_content from prd_db.beardo.dwh_AMAZON_FACT_ITEMS b left join (select * from ( select *,row_number()over(partition by reference_code, order_Date order by last_update_date desc) rw from prd_db.beardo.DWH_UNICOMMERCE_FACT_ITEMS ) z where z.rw = 1 ) c on lower(replace(b.order_name,\'#\',\'\')) = lower(c.reference_code) and b.order_timestamp::date = c.order_date::date union all select Null as customer_id ,upper(SHOP_NAME) shop_name ,upper(marketplace) AS CHANNEL ,upper(marketplace) AS SOURCE ,ORDER_ID ,reference_code ,contact_num as PHONE ,customer_name as NAME ,email as EMAIL ,shipping_last_update_date AS SHIPPING_LAST_UPDATE_DATE ,SKU ,b.PRODUCT_ID ,PRODUCT_NAME AS PRODUCT_NAME ,CURRENCY ,upper(CITY) as city ,upper(STATE) AS State ,upper(ORDER_STATUS) order_status ,ORDER_DATE::date AS Order_Date ,b.order_date ,selling_price line_item_sales ,SHIPPING_PRICE ,SUBORDER_QUANTITY AS QUANTITY ,DISCOUNT AS DISCOUNT ,TAX ,SELLING_PRICE AS SELLING_PRICE ,NULL AS SHIPPINGPACKAGECODE ,upper(shipping_status) AS SHIPPINGPACKAGESTATUS ,sales_order_item_id as SALES_ORDER_ITEM_ID ,saleorderitemcode as saleorderitemcode ,INVOICE_ID as INVOICE_ID ,COURIER ,upper(shipping_status) AS SHIPPING_STATUS ,Manifest_date AS DISPATCH_DATE ,case when upper(shipping_status) in (\'DELIVERED\') then 1 end AS DELIVERED_STATUS ,IS_REFUND AS RETURN_FLAG ,case when is_refund = 1 then suborder_quantity::int end returned_quantity ,case when is_refund = 0 and lower(order_status) in (\'cancelled\') then suborder_quantity::int end cancelled_quantity ,new_customer_flag::varchar as NEW_CUSTOMER_FLAG ,NULL as ACQUISITION_PRODUCT ,case when upper(shipping_STATUS) in (\'DELIVERED\',\'DELIVERED TO ORIGIN\', \'RETURNED\', \'RTO\') then datediff(day,date(b.ORDER_DATE),date(shipping_Last_update_date)) else datediff(day,date(b.ORDER_DATE), getdate()) end::int AS DAYS_IN_SHIPMENT ,NULL AS ACQUSITION_DATE ,warehouse_name ,coalesce(s.Product_name_mapped,b.product_name) PRODUCT_NAME_FINAL ,coalesce(s.Product_Category_Mapped,b.product_category_mapped) PRODUCT_CATEGORY ,coalesce(s.Product_Sub_Category_Mapped,b.product_category_mapped) PRODUCT_SUB_CATEGORY ,Marketplace as GA_SOURCE ,Marketplace as GA_MEDIUM ,null as VIEW_ID ,payment_mode ,null as discount_code ,null as affiliate ,cast(null as string) as tag ,cast(null as string) final_utm_content from (select * from prd_db.beardo.DWH_UNICOMMERCE_FACT_ITEMS where lower(marketplace) not like (\'%shopify%\') and lower(marketplace) not like (\'%amazon%\') and lower(marketplace) not like (\'%amz%\') )b left join (select distinct \"Product Code\" skucode, name Product_name_mapped, BUSINESS Product_category_mapped, \"Category Name\" Product_Sub_Category_Mapped from datalake_db.beardo.mst_mapping_sku_master) S on lower(b.sku)=lower(s.skucode) ) where shop_name not in (\'AMAZON\'); create or replace table prd_db.Beardo.dwh_sales_consolidated_intermediate as select CUSTOMER_ID ,SHOP_NAME ,CHANNEL ,SOURCE ,ORDER_ID ,reference_code ,PHONE ,CUSTOMER_NAME ,EMAIL ,SHIPPING_LAST_UPDATE_DATE ,SKU ,PRODUCT_ID ,PRODUCT_NAME ,CURRENCY ,CITY ,STATE ,ORDER_STATUS ,ORDER_DATE ,order_timestamp ,SHIPPINGPACKAGECODE ,SHIPPINGPACKAGESTATUS ,SHIPPING_STATUS ,SALEORDERITEMCODE ,SALES_ORDER_ITEM_ID ,INVOICE_ID ,COURIER ,DISPATCH_DATE ,DELIVERED_STATUS ,RETURN_FLAG ,NEW_CUSTOMER_FLAG ,ACQUISITION_PRODUCT ,DAYS_IN_SHIPMENT ,ACQUSITION_DATE ,WAREHOUSE_NAME ,PRODUCT_NAME_FINAL ,PRODUCT_CATEGORY ,PRODUCT_SUB_CATEGORY ,GA_SOURCE ,GA_MEDIUM ,VIEW_ID ,payment_mode ,discount_code ,affiliate ,tag as tags ,coalesce(pcm.skucode_child, sku) SKU_CODE_CHILD ,coalesce(upper(pcm.productname),upper(PRODUCT_NAME_FINAL)) CHILD_PRODUCT_NAME ,coalesce(upper(pcm.category),upper(PRODUCT_CATEGORY)) CHILD_PRODUCT_CATEGORY ,coalesce(upper(pcm.sub_category), upper(PRODUCT_SUB_CATEGORY)) CHILD_PRODUCT_SUBCATEGORY ,ifnull(pcm.qty,0)*ifnull(sc.quantity,0) as QUANTITY_CHILD ,ifnull(pcm.qty,0)*ifnull(sc.RETURNED_QUANTITY,0) as RETURNED_QUANTITY_CHILD ,ifnull(pcm.qty,0)*ifnull(sc.CANCELLED_QUANTITY,0) as CANCELLED_QUANTITY_CHILD ,div0(ifnull(QUANTITY,0),count(1) over (partition by ORDER_ID,SALEORDERITEMCODE, SALES_ORDER_ITEM_ID, sku)) Quantity ,div0(ifnull(DISCOUNT,0), count(1) over (partition by ORDER_ID,SALEORDERITEMCODE, SALES_ORDER_ITEM_ID, sku)) DISCOUNT ,div0(ifnull(TAX,0),count(1) over (partition by ORDER_ID,SALEORDERITEMCODE, SALES_ORDER_ITEM_ID, sku)) TAX ,div0(ifnull(SHIPPING_PRICE,0),count(1) over (partition by ORDER_ID,SALEORDERITEMCODE, SALES_ORDER_ITEM_ID, sku)) SHIPPING_PRICE ,div0(ifnull(SELLING_PRICE,0),count(1) over (partition by ORDER_ID,SALEORDERITEMCODE, SALES_ORDER_ITEM_ID, sku)) SELLING_PRICE ,div0(ifnull(RETURNED_QUANTITY,0),count(1) over (partition by ORDER_ID,SALEORDERITEMCODE, SALES_ORDER_ITEM_ID, sku)) RETURNED_QUANTITY ,div0(ifnull(CANCELLED_QUANTITY,0),count(1) over (partition by ORDER_ID,SALEORDERITEMCODE, SALES_ORDER_ITEM_ID, sku)) CANCELLED_QUANTITY ,div0(ifnull(line_item_sales,0),count(1) over (partition by ORDER_ID,SALEORDERITEMCODE, SALES_ORDER_ITEM_ID, sku)) line_item_Sales from prd_db.BEARDO.dwh_sales_consolidated_pre_intermediate sc left join ( select * from ( select a.\"Product Code\" skucode, coalesce(b.\"BUSINESS\", a.\"BUSINESS\") category, coalesce(b.\"Category Name\", a.\"Category Name\") sub_category, coalesce(b.NAME, a.NAME) productname, coalesce(a.\"Component Product Code\", a.\"Product Code\") skucode_child, coalesce(a.\"Component Quantity\",1) qty, row_number() over (partition by a.\"Product Code\", a.\"Component Product Code\" order by 1) rw from datalake_db.beardo.mst_mapping_sku_master a left join (select * from datalake_db.beardo.mst_mapping_sku_master where Type = \'SIMPLE\') b on a.\"Component Product Code\" = b.\"Product Code\" ) where rw=1 ) pcm on replace(sc.sku,\' \',\'\') = replace(pcm.skucode,\' \',\'\') ; Create Or Replace Table prd_db.beardo.dwh_sales_consolidated_intermediate_shopify as select * from prd_db.beardo.dwh_sales_consolidated_intermediate where lower(ifnull(shop_name,\'\')) like \'%shopify%\'; CREATE OR REPLACE TABLE prd_db.beardo.dwh_Final_customerID AS WITH new_phone_numbers AS ( SELECT phone, email, contact_num, 19700000000 + dense_rank() OVER (ORDER BY contact_num ASC) AS maple_monk_id FROM ( SELECT DISTINCT RIGHT(REGEXP_REPLACE(phone, \'[^a-zA-Z0-9]+\', \'\'), 10) AS contact_num, email, phone phone FROM prd_db.beardo.dwh_sales_consolidated_intermediate_shopify where phone is not null ) a ), INT AS ( SELECT contact_num, email, COALESCE(maple_monk_id, id2) AS maple_monk_id FROM ( SELECT contact_num, email, maple_monk_id, 19800000000 + ROW_NUMBER() OVER (PARTITION BY maple_monk_id IS NULL ORDER BY email ASC) AS id2 FROM ( SELECT DISTINCT COALESCE(p.contact_num, RIGHT(REGEXP_REPLACE(e.contact_num, \'[^a-zA-Z0-9]+\', \'\'), 10)) AS contact_num, e.email, coalesce(p.maple_monk_id,pe.maple_monk_id) maple_monk_id FROM ( SELECT phone AS contact_num, email FROM prd_db.beardo.dwh_sales_consolidated_intermediate_shopify ) e LEFT JOIN new_phone_numbers p ON p.contact_num = RIGHT(REGEXP_REPLACE(e.contact_num, \'[^a-zA-Z0-9]+\', \'\'), 10) LEFT JOIN (select * from new_phone_numbers qualify row_number() over (partition by lower(email) order by 1) = 1) pe ON lower(pe.email) = lower(e.email) ) b ) ) SELECT contact_num, email, maple_monk_id FROM INT WHERE COALESCE(contact_num, email) IS NOT NULL; CREATE OR REPLACE TABLE prd_db.beardo.final_customer_tag_mapping AS WITH phone_map AS ( SELECT cid.maple_monk_id, cust.tags FROM datalake_db.beardo.trn_Shopify_beardo_CUSTOMERS cust INNER JOIN prd_db.beardo.dwh_Final_customerID cid ON RIGHT(REGEXP_REPLACE(cust.phone, \'[^a-zA-Z0-9]+\'), 10) = cid.contact_num WHERE trim(ifnull(cust.phone,\'\')) != \'\' ), email_map AS ( SELECT cid.maple_monk_id, cust.tags FROM datalake_db.beardo.trn_Shopify_beardo_CUSTOMERS cust INNER JOIN prd_db.beardo.dwh_Final_customerID cid ON cust.email = cid.email WHERE cust.email IS NOT NULL ), combined_links AS ( SELECT * FROM phone_map UNION SELECT * FROM email_map ) SELECT maple_monk_id AS customer_id_final, LISTAGG(DISTINCT tags, \', \') WITHIN GROUP (ORDER BY tags) AS shopify_customer_tag FROM combined_links GROUP BY 1; create or replace table prd_db.beardo.dwh_sales_consolidated CLUSTER BY (customer_id_final) as select coalesce(m.maple_monk_id_phone, d.maple_monk_id) as customer_id_final, min(order_date) over(partition by customer_id_final) as acquisition_date, min(case when lower(m.order_status) not in (\'cancelled\') then order_date end) over(partition by customer_id_final) as first_complete_order_date, m.*, coalesce(ssm.final_status,m.order_status, m.shipping_status) as final_status from ( select c.maple_monk_id as maple_monk_id_phone, o.* from prd_db.beardo.dwh_sales_consolidated_intermediate_shopify o left join ( select * from ( select contact_num phone, maple_monk_id, row_number() over (partition by contact_num order by maple_monk_id asc) magic from prd_db.beardo.dwh_Final_customerID ) where magic =1 )c on c.phone = right(regexp_replace(o.phone, \'[^a-zA-Z0-9]+\'),10) )m left join ( select distinct maple_monk_id, email from prd_db.beardo.dwh_Final_customerID where contact_num is null )d on d.email = m.email left join datalake_db.beardo.mst_shipment_status_mapping ssm on upper(ifnull(ssm.shipping_status,\'a\')) = upper(ifnull(m.shipping_status,\'a\')) and upper(ssm.order_status) = upper(m.order_status) ; CREATE OR REPLACE TABLE prd_db.beardo.dwh_sales_consolidated AS SELECT s.*, t.shopify_customer_tag, dn.order_number from prd_db.beardo.dwh_sales_consolidated s LEFT JOIN prd_db.beardo.final_customer_tag_mapping t ON s.customer_id_final = t.customer_id_final left join ( select customer_id_final, order_id, order_Date, dense_rank() over(partition by customer_id_final order by order_id,order_date::date asc) order_number from ( select distinct customer_id_final, order_id, order_Date::date as order_Date from prd_db.beardo.dwh_sales_consolidated ) )dn on dn.customer_id_final = s.customer_id_final and dn.order_id = s.order_id ; ALTER TABLE prd_db.beardo.dwh_sales_consolidated drop COLUMN new_customer_flag ; ALTER TABLE prd_db.beardo.dwh_sales_consolidated ADD COLUMN new_customer_flag varchar(50); ALTER TABLE prd_db.beardo.dwh_sales_consolidated ADD COLUMN new_customer_flag_month varchar(50); ALTER TABLE prd_db.beardo.dwh_sales_consolidated drop COLUMN acquisition_product ; ALTER TABLE prd_db.beardo.dwh_sales_consolidated ADD COLUMN acquisition_product varchar(16777216); ALTER TABLE prd_db.beardo.dwh_sales_consolidated ADD COLUMN acquisition_SKUCODE varchar(16777216); ALTER TABLE prd_db.beardo.dwh_sales_consolidated ADD COLUMN acquisition_PRODUCT_SUB_CATEGORY varchar(16777216); ALTER TABLE prd_db.beardo.dwh_sales_consolidated ADD COLUMN acquisition_PRODUCT_CATEGORY varchar(16777216); ALTER TABLE prd_db.beardo.dwh_sales_consolidated ADD COLUMN acquisition_channel varchar(16777216); ALTER TABLE prd_db.beardo.dwh_sales_consolidated ADD COLUMN acquisition_marketplace varchar(16777216); UPDATE prd_db.beardo.dwh_sales_consolidated as a SET A.new_customer_flag = B.flag FROM ( SELECT DISTINCT order_id, customer_id_final, Order_Date, CASE WHEN Order_Date = first_complete_order_date then \'New\' WHEN Order_Date < first_complete_order_date or first_complete_order_date is null THEN \'Yet to make completed order\' WHEN Order_Date > first_complete_order_date then \'Repeat\' END AS Flag FROM prd_db.beardo.dwh_sales_consolidated)AS B WHERE A.order_id = B.order_id AND A.customer_id_final = B.customer_id_final AND A.order_date::date=B.Order_date::Date ; UPDATE prd_db.beardo.dwh_sales_consolidated SET new_customer_flag = CASE WHEN new_customer_flag IS NULL and (case when lower(order_status) is null then 1=1 else lower(order_status) not in (\'cancelled\') end) THEN \'New\' WHEN new_customer_flag IS NULL and (case when lower(order_status) is null then 1=1 else lower(order_status) in (\'cancelled\') end) THEN \'Yet to make completed order\' ELSE new_customer_flag END; UPDATE prd_db.beardo.dwh_sales_consolidated AS A SET A.new_customer_flag_month = B.flag FROM ( SELECT DISTINCT order_id, customer_id_final, Order_Date, CASE WHEN Last_day(order_date, \'month\') = Last_day(first_complete_order_date, \'month\') THEN \'New\' WHEN Last_day(order_date, \'month\') < Last_day(first_complete_order_date, \'month\') or acquisition_date is null THEN \'Yet to make completed order\' WHEN Last_day(order_date, \'month\') > Last_day(first_complete_order_date, \'month\') THEN \'Repeat\' END AS Flag FROM prd_db.beardo.dwh_sales_consolidated)AS B WHERE A.order_id = B.order_id AND A.customer_id_final = B.customer_id_final; UPDATE prd_db.beardo.dwh_sales_consolidated SET new_customer_flag_month = CASE WHEN new_customer_flag_month IS NULL and (case when lower(order_status) is null then 1=1 else lower(order_status) not in (\'cancelled\') end) THEN \'New\' ELSE new_customer_flag_month END; create or replace temporary table prd_db.beardo.dwh_temp_source_1 AS SELECT DISTINCT customer_id_final, channel, marketplace FROM ( SELECT DISTINCT customer_id_final, order_timestamp, source as channel, shop_name as marketplace, Min(case when lower(order_status) <> \'cancelled\' then order_timestamp end) OVER ( partition BY customer_id_final) firstOrderdate FROM prd_db.beardo.dwh_sales_consolidated ) res WHERE ordeR_timestamp=firstorderdate; UPDATE prd_db.beardo.dwh_sales_consolidated AS a SET a.acquisition_channel=b.channel FROM prd_db.beardo.dwh_temp_source_1 b WHERE a.customer_id_final = b.customer_id_final; UPDATE prd_db.beardo.dwh_sales_consolidated AS a SET a.acquisition_marketplace=b.marketplace FROM prd_db.beardo.dwh_temp_source_1 b WHERE a.customer_id_final = b.customer_id_final; CREATE OR replace temporary TABLE prd_db.beardo.dwh_temp_product_1 AS SELECT DISTINCT customer_id_final, product_name_final, product_category, product_sub_category, sku, Row_number() OVER (partition BY customer_id_final ORDER BY SELLING_PRICE DESC) rowid FROM ( SELECT DISTINCT customer_id_final, order_date, product_name_final, product_category, product_sub_category, sku, SELLING_PRICE, Min(case when lower(order_status) <> \'cancelled\' then order_date end) OVER (partition BY customer_id_final) firstOrderdate FROM prd_db.beardo.dwh_sales_consolidated )res WHERE order_date=firstorderdate; CREATE OR replace temporary TABLE prd_db.beardo.vip_product AS SELECT DISTINCT customer_id_final, product_name_final, true as is_vip_acquired, Row_number() OVER (partition BY customer_id_final ORDER BY SELLING_PRICE DESC) rowid FROM ( SELECT DISTINCT customer_id_final, order_date, product_name_final, selling_price, Min(case when lower(order_status) <> \'cancelled\' then order_date end) OVER (partition BY customer_id_final) firstOrderdate FROM prd_db.beardo.dwh_sales_consolidated where lower(product_name_final) like \'%vip membership%\' )res WHERE order_date=firstorderdate; UPDATE prd_db.beardo.dwh_sales_consolidated AS A SET A.acquisition_product=B.product_name_final FROM ( SELECT * FROM prd_db.beardo.dwh_temp_product_1 WHERE rowid=1 )B WHERE A.customer_id_final = B.customer_id_final; UPDATE prd_db.beardo.dwh_sales_consolidated AS A SET A.acquisition_product_category=B.product_category FROM ( SELECT * FROM prd_db.beardo.dwh_temp_product_1 WHERE rowid=1 )B WHERE A.customer_id_final = B.customer_id_final; UPDATE prd_db.beardo.dwh_sales_consolidated AS A SET A.acquisition_product_sub_category=B.product_sub_category FROM ( SELECT * FROM prd_db.beardo.dwh_temp_product_1 WHERE rowid=1 )B WHERE A.customer_id_final = B.customer_id_final; UPDATE prd_db.beardo.dwh_sales_consolidated AS A SET A.acquisition_SKUCODE=B.SKU FROM ( SELECT * FROM prd_db.beardo.dwh_temp_product_1 WHERE rowid=1 )B WHERE A.customer_id_final = B.customer_id_final; ALTER TABLE prd_db.beardo.dwh_sales_consolidated ADD COLUMN acquisition_type varchar(16777216); UPDATE prd_db.beardo.dwh_sales_consolidated AS A SET A.acquisition_type = case when B.is_vip_acquired then \'VIP Member\' else null end FROM ( SELECT * FROM prd_db.beardo.vip_product WHERE rowid=1 )B WHERE A.customer_id_final = B.customer_id_final; Create Or Replace table prd_db.beardo.dwh_sales_consolidated as ( SELECT CUSTOMER_ID_FINAL ,ACQUISITION_DATE ,FIRST_COMPLETE_ORDER_DATE ,MAPLE_MONK_ID_PHONE ,CUSTOMER_ID ,SHOP_NAME ,CHANNEL ,SOURCE ,ORDER_ID ,REFERENCE_CODE ,PHONE ,CUSTOMER_NAME ,EMAIL ,SHIPPING_LAST_UPDATE_DATE ,SKU ,PRODUCT_ID ,PRODUCT_NAME ,CURRENCY ,CITY ,STATE ,ORDER_STATUS ,ORDER_DATE ,ORDER_TIMESTAMP ,SHIPPINGPACKAGECODE ,SHIPPINGPACKAGESTATUS ,SHIPPING_STATUS ,SALEORDERITEMCODE ,SALES_ORDER_ITEM_ID ,INVOICE_ID ,COURIER ,DISPATCH_DATE ,DELIVERED_STATUS ,RETURN_FLAG ,DAYS_IN_SHIPMENT ,ACQUSITION_DATE ,WAREHOUSE_NAME ,PRODUCT_NAME_FINAL ,PRODUCT_CATEGORY ,PRODUCT_SUB_CATEGORY ,GA_SOURCE ,GA_MEDIUM ,VIEW_ID ,PAYMENT_MODE ,DISCOUNT_CODE ,AFFILIATE ,TAGS ,SKU_CODE_CHILD ,CHILD_PRODUCT_NAME ,CHILD_PRODUCT_CATEGORY ,CHILD_PRODUCT_SUBCATEGORY ,QUANTITY_CHILD ,RETURNED_QUANTITY_CHILD ,CANCELLED_QUANTITY_CHILD ,QUANTITY ,DISCOUNT ,TAX ,SHIPPING_PRICE ,SELLING_PRICE ,RETURNED_QUANTITY ,CANCELLED_QUANTITY ,LINE_ITEM_SALES ,FINAL_STATUS ,SHOPIFY_CUSTOMER_TAG ,ORDER_NUMBER ,NEW_CUSTOMER_FLAG ,NEW_CUSTOMER_FLAG_MONTH ,ACQUISITION_PRODUCT ,ACQUISITION_SKUCODE ,ACQUISITION_PRODUCT_SUB_CATEGORY ,ACQUISITION_PRODUCT_CATEGORY ,ACQUISITION_CHANNEL ,ACQUISITION_MARKETPLACE ,ACQUISITION_TYPE FROM prd_db.beardo.dwh_sales_consolidated ) union all ( SELECT NULL CUSTOMER_ID_FINAL ,NULL ACQUISITION_DATE ,NULL FIRST_COMPLETE_ORDER_DATE ,NULL MAPLE_MONK_ID_PHONE ,CUSTOMER_ID ,SHOP_NAME ,CHANNEL ,SOURCE ,ORDER_ID ,REFERENCE_CODE ,PHONE ,CUSTOMER_NAME ,EMAIL ,SHIPPING_LAST_UPDATE_DATE ,SKU ,PRODUCT_ID ,PRODUCT_NAME ,CURRENCY ,CITY ,STATE ,m.ORDER_STATUS ,ORDER_DATE ,ORDER_TIMESTAMP ,SHIPPINGPACKAGECODE ,SHIPPINGPACKAGESTATUS ,m.SHIPPING_STATUS ,SALEORDERITEMCODE ,SALES_ORDER_ITEM_ID ,INVOICE_ID ,COURIER ,DISPATCH_DATE ,DELIVERED_STATUS ,RETURN_FLAG ,DAYS_IN_SHIPMENT ,ACQUSITION_DATE ,WAREHOUSE_NAME ,PRODUCT_NAME_FINAL ,PRODUCT_CATEGORY ,PRODUCT_SUB_CATEGORY ,GA_SOURCE ,GA_MEDIUM ,VIEW_ID ,PAYMENT_MODE ,DISCOUNT_CODE ,AFFILIATE ,TAGS ,SKU_CODE_CHILD ,CHILD_PRODUCT_NAME ,CHILD_PRODUCT_CATEGORY ,CHILD_PRODUCT_SUBCATEGORY ,QUANTITY_CHILD ,RETURNED_QUANTITY_CHILD ,CANCELLED_QUANTITY_CHILD ,QUANTITY ,DISCOUNT ,TAX ,SHIPPING_PRICE ,SELLING_PRICE ,RETURNED_QUANTITY ,CANCELLED_QUANTITY ,LINE_ITEM_SALES ,coalesce(ssm.final_status,m.order_status, m.shipping_status) as final_status ,NULL SHOPIFY_CUSTOMER_TAG ,NULL ORDER_NUMBER ,NULL NEW_CUSTOMER_FLAG ,NULL NEW_CUSTOMER_FLAG_MONTH ,NULL ACQUISITION_PRODUCT ,NULL ACQUISITION_SKUCODE ,NULL ACQUISITION_PRODUCT_SUB_CATEGORY ,NULL ACQUISITION_PRODUCT_CATEGORY ,NULL ACQUISITION_CHANNEL ,NULL ACQUISITION_MARKETPLACE ,NULL ACQUISITION_TYPE FROM prd_db.Beardo.dwh_sales_consolidated_intermediate m left join datalake_db.beardo.mst_shipment_status_mapping ssm on upper(ifnull(ssm.shipping_status,\'a\')) = upper(ifnull(m.shipping_status,\'a\')) and upper(ssm.order_status) = upper(m.order_status) where NOT(lower(ifnull(shop_name,\'\')) like \'%shopify%\') ) ; create or replace table prd_db.beardo.dwh_unicommerce_returns_detailed as select a.order_date ,a.reference_code ,b.channel marketing_channel ,upper(shop_name) as marketplace ,sum(a.returned_quantity) RETURN_QUANTITY ,sum(a.return_sales) RETURN_sales ,sum(case when is_refund = 1 then TAX end) TOTAL_RETURN_TAX ,sum(return_sales) - TOTAL_RETURN_TAX as TOTAL_RETURN_AMOUNT_EXCL_TAX from prd_db.beardo.dwh_unicommerce_fact_items a left join (select distinct reference_code, channel from prd_db.beardo.dwh_sales_consolidated) b on lower(replace(a.reference_code,\'#\',\'\')) = lower(replace(b.reference_code,\'#\',\'\')) group by 1,2,3,4; create or replace table prd_db.beardo.dwh_Unicommerce_RETURNS_SUMMARY_Beardo as select upper(marketplace) Marketplace ,upper(marketing_channel) marketing_channel ,order_date ,sum(RETURN_QUANTITY) TOTAL_RETURNED_QUANTITY ,sum(RETURN_sales) TOTAL_RETURN_AMOUNT ,sum(TOTAL_RETURN_TAX) TOTAL_RETURN_TAX ,TOTAL_RETURN_AMOUNT - sum(TOTAL_RETURN_TAX) as TOTAL_RETURN_AMOUNT_EXCL_TAX from prd_db.beardo.dwh_unicommerce_returns_detailed group by 1,2,3;",
                    "transaction": true
                }
            ) }}
